
local ytw=[==[]==]
local zcgrk=
(function(...)
local oswvb={170,52,239,166,117,175,20,137,186,112,138,25,174,227,79,22,48,235,131,253,5,175,168,176}
local bfmg=bit32 or bit
local sf=bfmg.bxor
for ulowx=1,#oswvb do oswvb[ulowx]=sf(oswvb[ulowx],(16*ulowx+14)%256) end
local hkpa="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local wkrz={}
for vdg=1,#hkpa do wkrz[hkpa:byte(vdg)]=vdg-1 end
local function vwg(str)
  local R={} local acc,nb=0,0
  for vmd=1,#str do
    local v=wkrz[str:byte(vmd)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function cb(key,data)
  local S={} for zl=0,255 do S[zl]=zl end
  local j=0
  for vjz=0,255 do
    j=(j+S[vjz]+key[(vjz%#key)+1])%256
    S[vjz],S[j]=S[j],S[vjz]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(sf(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=cb(oswvb,vwg(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local vypc=nf()
return function(big) return vypc(big) end
end)(...)

return zcgrk(ytw)
